print("\n🎯 Phase 3: Optimizing Bias with Coordinate Descent...")

def get_tuned_preds(probs, bias):
    # Apply bias in logit space
    adjusted = logit(np.clip(probs, 1e-15, 1.0 - 1e-15)) + bias
    return np.argmax(adjusted, axis=1)

best_bias = np.zeros(3); best_score = raw_cv_ba; opt_history = [best_score]
for step in [1.0, 0.5, 0.2, 0.1, 0.05, 0.02, 0.01, 0.005, 0.002]:
    improved = True
    while improved:
        improved = False
        for ci in range(3):
            for d in [1, -1]:
                trial_bias = best_bias.copy(); trial_bias[ci] += d * step
                s = balanced_accuracy_score(y_train_full, get_tuned_preds(oof_probs, trial_bias))
                if s > best_score + 1e-9:
                    best_score, best_bias, improved = s, trial_bias, True
                    opt_history.append(best_score)

print(f"✨ Found Optimal Biases [Low, Medium, High]: {best_bias}")
print(f"📈 Tuned CV Balanced Accuracy: {best_score:.6f} (+{best_score - raw_cv_ba:.6f})")
